module XGMII_top #(
  parameter int DEPTH = 16
)(
  input  logic        clk,
  input  logic        rst_n,
  input  logic        tx_clk,
  output logic [31:0] txd,
  output logic [3:0]  txc,
  input  logic        rx_clk,
  input  logic [31:0] rxd,
  input  logic [3:0]  rxc,
  input  logic        wen,
  input  logic [3:0]  waddr,     // 0: data byte, 1: end of frame (flush)
  input  logic [7:0]  wdata,
  input  logic        ren,
  input  logic [3:0]  raddr,
  output logic [7:0]  rdata,
  output logic [4:0]  count,
  output logic        irq
);
  // ---------------- TX: byte packer + 4-word async FIFO, clk -> tx_clk ----
  // Host bytes (waddr 0) are packed little-lane first into a 32-bit word;
  // a full word is pushed, and a write to waddr 1 (end of frame) pushes a
  // pending partial word. Each FIFO entry carries its byte count, so the
  // read side pops exactly one entry per tx_clk and the pointers move one
  // step at a time (Gray-safe). A byte that would complete a word while the
  // FIFO is full is dropped, as is an end-of-frame while full.
  logic [31:0] wq_d [0:3];
  logic [1:0]  wq_n [0:3];              // bytes in the word minus 1
  logic [2:0]  tw_bin, tw_gray, tr_bin, tr_gray;
  logic [2:0]  tr_gray_s1, tr_gray_s2;  // read pointer seen in clk domain
  logic [2:0]  tw_gray_s1, tw_gray_s2;  // write pointer seen in tx_clk domain
  logic [23:0] pk_d;                    // packed bytes 0..2 of the open word
  logic [1:0]  pk_n;                    // bytes held in the packer
  wire  [2:0]  tw_next  = tw_bin + 3'd1;
  wire  [2:0]  tr_next  = tr_bin + 3'd1;
  wire         tx_full  = (tw_gray == {~tr_gray_s2[2:1], tr_gray_s2[0]});
  wire         tx_empty = (tr_gray == tw_gray_s2);
  wire         wr_byte  = wen && waddr == 4'd0;
  wire         wr_eof   = wen && waddr == 4'd1;
  wire         push_full = wr_byte && pk_n == 2'd3 && !tx_full;
  wire         push_part = wr_eof && pk_n != 2'd0 && !tx_full;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tw_bin <= '0; tw_gray <= '0; tr_gray_s1 <= '0; tr_gray_s2 <= '0;
      pk_d <= '0; pk_n <= '0;
    end else begin
      tr_gray_s1 <= tr_gray; tr_gray_s2 <= tr_gray_s1;
      if (push_full || push_part) begin
        wq_d[tw_bin[1:0]] <= push_full ? {wdata, pk_d} : {8'h0, pk_d};
        wq_n[tw_bin[1:0]] <= push_full ? 2'd3 : pk_n - 2'd1;
        tw_bin  <= tw_next;
        tw_gray <= tw_next ^ (tw_next >> 1);
        pk_n    <= 2'd0;
      end else if (wr_byte && pk_n != 2'd3) begin
        case (pk_n)
          2'd0:    pk_d[7:0]   <= wdata;
          2'd1:    pk_d[15:8]  <= wdata;
          default: pk_d[23:16] <= wdata;
        endcase
        pk_n <= pk_n + 2'd1;
      end
    end
  end

  wire [31:0] rd_word = wq_d[tr_bin[1:0]];
  wire [1:0]  rd_n    = wq_n[tr_bin[1:0]];
  // lanes 3..1 above the byte count are control (lane 0 always carries data)
  wire [3:1]  rd_ctl  = {rd_n != 2'd3, rd_n < 2'd2, rd_n == 2'd0};

  // one column per tx_clk: data lanes from lane 0 up, the rest are idle
  // control characters (0x07, txc=1); an empty FIFO sends an idle column
  always_ff @(posedge tx_clk or negedge rst_n) begin
    if (!rst_n) begin
      txd <= 32'h0707_0707; txc <= 4'hF;
      tr_bin <= '0; tr_gray <= '0; tw_gray_s1 <= '0; tw_gray_s2 <= '0;
    end else begin
      tw_gray_s1 <= tw_gray; tw_gray_s2 <= tw_gray_s1;
      if (!tx_empty) begin
        txd <= {rd_ctl[3] ? 8'h07 : rd_word[31:24], rd_ctl[2] ? 8'h07 : rd_word[23:16],
                rd_ctl[1] ? 8'h07 : rd_word[15:8],  rd_word[7:0]};
        txc <= {rd_ctl, 1'b0};
        tr_bin  <= tr_next;
        tr_gray <= tr_next ^ (tr_next >> 1);
      end else begin
        txd <= 32'h0707_0707; txc <= 4'hF;
      end
    end
  end

  // ---------------- RX: oversampled capture ring (16 x 8) ----------------
  // rxd/rxc are sampled on the same clk edge as the first rx_clk stage. On
  // each rx_clk rising edge every data lane (rxc=0) is stored, compacted in
  // lane order; control lanes are skipped wherever they sit in the column.
  logic [7:0]  rxq [0:DEPTH-1];
  logic [4:0]  rx_wr;
  logic        rxclk_s, rxclk_d;
  logic [31:0] rxd_s;
  logic [3:0]  rxc_s;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin rxclk_s <= 1'b0; rxclk_d <= 1'b0; rxd_s <= '0; rxc_s <= 4'hF; end
    else begin rxclk_s <= rx_clk; rxclk_d <= rxclk_s; rxd_s <= rxd; rxc_s <= rxc; end
  end
  wire       rxv_rise = rxclk_s & ~rxclk_d;
  wire [3:0] dl   = ~rxc_s;                    // data lanes
  wire       off1 = dl[0];                     // slot of lane i = data lanes below i
  wire [1:0] off2 = {1'b0, off1} + {1'b0, dl[1]};
  wire [1:0] off3 = off2 + {1'b0, dl[2]};
  wire [2:0] ndat = {1'b0, off3} + {2'd0, dl[3]};

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) rx_wr <= '0;
    else if (rxv_rise) begin
      if (dl[0]) rxq[rx_wr[3:0]]        <= rxd_s[7:0];
      if (dl[1]) rxq[rx_wr[3:0] + {3'd0, off1}] <= rxd_s[15:8];
      if (dl[2]) rxq[rx_wr[3:0] + {2'd0, off2}] <= rxd_s[23:16];
      if (dl[3]) rxq[rx_wr[3:0] + {2'd0, off3}] <= rxd_s[31:24];
      rx_wr <= rx_wr + {2'd0, ndat};
    end
  end

  assign count = rx_wr;
  assign rdata = rxq[raddr[3:0]];
  assign irq   = (rx_wr != 0) && ren;

endmodule
